const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Polygon([[
        [50.0, 25.0], [62.0, 25.0], [62.0, 30.0], [50.0, 30.0], [50.0, 25.0]
    ]], null, false);

    const date1_start = '2020-01-08';
    const date1_end = '2020-01-09';
    const date2_start = '2020-01-13';
    const date2_end = '2020-01-14';

    // 2. Data Acquisition
    const s1_collection = ee.ImageCollection('COPERNICUS/S1_GRD')
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
        .filter(ee.Filter.eq('instrumentMode', 'IW'))
        .filterBounds(geometry);

    const col1 = s1_collection.filterDate(date1_start, date1_end);
    const col2 = s1_collection.filterDate(date2_start, date2_end);

    const col1_size = col1.size().getInfo();
    const col2_size = col2.size().getInfo();

    console.log(`Images for ${date1_start}: ${col1_size}`);
    console.log(`Images for ${date2_start}: ${col2_size}`);

    if (col1_size === 0 || col2_size === 0) {
        console.log("Evidence: No Sentinel-1 images found for one or both dates.");
        console.log("C1");
        return;
    }

    // 3. Processing
    const image1 = col1.mosaic().clip(geometry);
    const image2 = col2.mosaic().clip(geometry);

    // Water is identified by low backscatter values (e.g., < -16 dB)
    const water_threshold = -16;
    const water_mask1 = image1.select('VV').lt(water_threshold).selfMask();
    const water_mask2 = image2.select('VV').lt(water_threshold).selfMask();

    // 4. Calculation
    // Use ee.Reducer.sum() on the binary mask. The pixel value is 1, so sum is equivalent to count.
    const reducer = ee.Reducer.sum();
    const scale = 3000; // Use a coarse scale for a large area to avoid timeouts.

    const water_pixels1_result = water_mask1.reduceRegion({
        reducer: reducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e12
    }).get('VV');

    const water_pixels2_result = water_mask2.reduceRegion({
        reducer: reducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e12
    }).get('VV');

    const water_pixels1 = water_pixels1_result.getInfo();
    const water_pixels2 = water_pixels2_result.getInfo();

    // 5. Validation & Final Answer
    if (water_pixels1 === null || water_pixels2 === null) {
        console.log("Evidence: Calculation resulted in null, possibly no water pixels or error.");
        console.log("C3");
        return;
    }

    if (water_pixels1 === 0 && water_pixels2 === 0) {
        console.log("Evidence: No water pixels detected on either date after applying threshold.");
        console.log("C2");
        return;
    }

    console.log(`Water Pixel Count on ${date1_start}: ${water_pixels1.toFixed(0)}`);
    console.log(`Water Pixel Count on ${date2_start}: ${water_pixels2.toFixed(0)}`);

    if (water_pixels2 > water_pixels1) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
